export function normalizeLanguage(value) {
  const code = String(value || '').toLowerCase().split(/[-_]/)[0];
  return TEXTS[code] ? code : 'de';
}

export function createI18n({ search = '', storage = null, navigatorLanguage = '' } = {}) {
  const query = new URLSearchParams(search).get('lang');
  let language = normalizeLanguage(query || storage?.getItem?.('atlas-language-v1') || navigatorLanguage || 'de');
  return {
    get language() { return language; },
    get locale() { return LANGUAGES.find(item => item.code === language)?.locale || 'de-DE'; },
    t(key, vars = {}) {
      const template = TEXTS[language]?.[key] ?? en[key] ?? de[key] ?? key;
      return String(template).replace(/\{(\w+)\}/g, (_, name) => String(vars[name] ?? ''));
    },
    setLanguage(value, persist = true) {
      language = normalizeLanguage(value);
      if (persist) storage?.setItem?.('atlas-language-v1', language);
      return language;
    }
  };
}

export function translateCategory(value, language = 'de') {
  if (language === 'de') return value;
  return CATEGORY_TEXT[language]?.[value] || CATEGORY_TEXT.en[value] || value;
}

export function formatLocalizedYear(event, i18n) {
  if (event.dateLabel && i18n.language === 'de') return event.dateLabel;
  if (!event.yearStart) return i18n.t('undated');
  if (event.yearStart < 0) return i18n.t('yearsAgo', { year: Math.abs(event.yearStart).toLocaleString(i18n.locale) });
  if (!event.yearEnd || event.yearStart === event.yearEnd) return String(event.yearStart);
  return `${event.yearStart}–${event.yearEnd}`;
}
